using marble_physics::Mem;
using marble_physics::PLAYER;

// object fields
static const uint8_t PX = 0x0c, PY = 0x10, PZ = 0x14, SLOT = 0x18, IDX = 0x19;
static const uint8_t ZONE = 0x1b, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, MASKS = 0x38;
static const uint8_t ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t A_TICK = 0x24, A_SCREEN = 0x28, A_CURSOR = 0x2c, A_FRAME = 0x3a;
static const uint8_t A_BAND_LO = 0x34, A_BAND_HI = 0x36;
static const uint8_t MASK_BYTES = 30;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint32_t LIST = 0x4003bc, ENTRIES = 0x4001dc;  // draw list bytes, entries
static const uint8_t ENTRY_SIZE = 14, LIST_MAX = 31, LIST_END = 0xff;
static const uint8_t TYPE_ACID = 0xe;
static const uint8_t RACES = 6, RACE_SILLY = 4;
static const int16_t SWEEP_STEP = 4;  // marble_mo.SWEEP_STEP
static const uint16_t DISSOLVE_TICKS = 600;

static uint8_t ram[marble_physics::RAM_SIZE];

static uint32_t acid(uint8_t i) { return marble_enemies::ACIDS + marble_enemies::ACID_SIZE * i; }

static void loadRam(const MarbleAcidSegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarbleAcidRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// draw list entry k in link order: type << 8 | index, -1 past the end
static int16_t entryAt(const Mem &m, uint8_t k) {
  if (k >= LIST_MAX || m.rb(LIST + k) == LIST_END) { return -1; }
  const uint32_t e = ENTRIES + ENTRY_SIZE * m.rb(LIST + k);
  return (int16_t)(m.rb(e) << 8 | m.rb(e + 1));
}

static uint8_t listedCount(const Mem &m, uint8_t type, uint8_t idx) {
  uint8_t n = 0;
  for (uint8_t k = 0; entryAt(m, k) >= 0; k++) { n += entryAt(m, k) == (type << 8 | idx); }
  return n;
}

// player frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62
static uint32_t playerHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == marble_physics::EATEN || st == marble_physics::DISSOLVING;
  return m.rb(PLAYER + VISIBLE) && drawn ? marble_physics::animEntry(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m) {
  return m.rb(PLAYER + VISIBLE) && m.rb(PLAYER + SHARDS_ON) ? marble_physics::animEntry(m.rl(PLAYER + SHARDS)) : 0;
}

static const char *playerDiff(const Mem &m, const MarbleAcidTick &t) {
  if (marble_physics::x(m) != t.x) { return "player x"; }
  if (marble_physics::y(m) != t.y) { return "player y"; }
  if (marble_physics::z(m) != t.z) { return "player z"; }
  if (marble_physics::state(m) != t.state) { return "player state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "player vis"; }
  if (m.sw(PLAYER + SX) != t.sx || m.sw(PLAYER + SY) != t.sy) { return "player sx/sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "player anim"; }
  if (playerHdr(m) != t.frame_hdr) { return "player frame"; }
  if (shardHdr(m) != t.shard_hdr) { return "player shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "player mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// acid frame drawn: rl(frame cursor) while live and listed, else 0
static uint32_t acidHdr(const Mem &m, uint8_t i) {
  const uint32_t a = acid(i);
  return m.rb(a + SLOT) && listedCount(m, TYPE_ACID, i) ? marble_physics::animEntry(m.rl(a + A_FRAME)) : 0;
}

static const char *acidDiff(const Mem &m, uint8_t i, const MarbleAcidObj &s) {
  const uint32_t a = acid(i);
  if (m.rb(a + SLOT) != s.live) { return "acid live"; }
  if (m.sl(a + PX) != s.x || m.sl(a + PY) != s.y) { return "acid x/y"; }
  if (m.sl(a + PZ) != s.z) { return "acid z"; }
  if (m.sw(a + A_SCREEN) != s.sx || m.sw(a + A_SCREEN + 2) != s.sy) { return "acid sx/sy"; }
  if (m.rw(a + A_TICK) != s.tick) { return "acid tick"; }
  if (m.rl(a + A_CURSOR) != s.path) { return "acid path"; }
  if (m.rl(a + A_FRAME) != s.cursor) { return "acid cursor"; }
  if (acidHdr(m, i) != s.frame_hdr) { return "acid frame"; }
  return nullptr;
}

static const char *listDiff(const Mem &m, const MarbleAcidSegment &seg, const MarbleAcidTick &t) {
  for (uint8_t k = 0; k < t.nlist; k++) {
    const MarbleAcidEntry &e = seg.list[t.lfirst + k];
    if (entryAt(m, k) != (e.type << 8 | e.index)) { return "draw list"; }
  }
  return entryAt(m, t.nlist) < 0 ? nullptr : "draw list length";
}

// One main loop tick as marble_acid.py replays it: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (old camera still stored, as 0x13ee6), player 0x251de, steelies
// 0x158cc, slinkies 0x1493c, acid 0x17230, slots 0x12fd0, rng, the 0x26f3e sort.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const int16_t old = m.sw(marble_physics::CAMERA);
  if ((int16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

static void test_replay_acid(void) {
  for (uint8_t s = 0; s < MARBLE_ACID_SEGMENTS; s++) {
    const MarbleAcidSegment &seg = marble_acid_segments[s];
    loadRam(seg);
    Mem m(ram, seg.race);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleAcidTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      const char *bad = playerDiff(m, t);
      int8_t which = -1;
      for (uint8_t i = 0; i < marble_enemies::NACIDS && !bad; i++) {
        bad = acidDiff(m, i, t.a[i]);
        which = (int8_t)i;
      }
      if (!bad) {
        bad = listDiff(m, seg, t);
        which = -1;
      }
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "segment %d (race %d frame %u) tick %d: acid %d %s differs", s,
               seg.race, (unsigned)seg.frame, k, which, bad);
      TEST_FAIL_MESSAGE(msg);
    }
  }
}

// ---------------------------------------------------------------- acid objects

// One MO as the published state draws it: race pixel top left, height, hflip
struct DrawnMo {
  int16_t x, top;
  uint8_t h;
  bool flip;
};

static const uint8_t PAL_ACID = 6;  // MO palette set of the acid frames
static const uint8_t MOS_MAX = 16;  // frame columns of one acid

// acid j live with the same screen position and frame cursor as acid i (same object)
static bool twin(const Mem &m, uint8_t i, uint8_t j) {
  const uint32_t a = acid(i), b = acid(j);
  return m.rb(b + SLOT) && m.rl(b + A_SCREEN) == m.rl(a + A_SCREEN) &&
         m.rl(b + A_FRAME) == m.rl(a + A_FRAME);
}

// MOs of acid i in v: its object (frame rl(+0x3a)) at the origin (+0x28, top + ARCADE_H -
// +0x2a); acid on the same spot with the same frame (crawling the same cells) are told apart
// by index order
static uint8_t acidMos(const Mem &m, const marble_video::VideoState &v, uint8_t i, int16_t top,
                       DrawnMo *out) {
  using namespace marble_video;
  const uint32_t a = acid(i);
  if (!m.rb(a + SLOT)) { return 0; }
  const int16_t ox = m.sw(a + A_SCREEN);
  const int16_t oy = (int16_t)(top + ARCADE_H - m.sw(a + A_SCREEN + 2));
  const MarbleSpriteSet &ds = marble_physics::deathSet();
  const uint8_t frame = marble_physics::deathFrame(marble_physics::animEntry(m.rl(a + A_FRAME)));
  uint8_t skip = 0;
  for (uint8_t j = 0; j < i; j++) { skip += twin(m, i, j); }
  uint8_t k = 0;
  for (uint8_t j = 0; j < v.n; j++) {
    const Obj &o = v.objs[j];
    if (o.x != ox || o.y != oy || o.set != (SET_DEATH | SET_ACID) || o.frame != frame) {
      continue;
    }
    if (skip) {
      skip--;
      continue;
    }
    TEST_ASSERT_EQUAL_UINT8(0, o.nmask);
    const MarbleSpriteFrame &f = ds.frames()[o.frame];
    for (uint8_t c = 0; c < f.ncols && k < MOS_MAX; c++) {
      const MarbleSpriteCol &col = ds.cols()[f.first + c];
      out[k++] = {(int16_t)(o.x + col.x), (int16_t)(o.y + col.y), (uint8_t)(col.h & 0x7f),
                  (col.h & 0x80) != 0};
    }
    break;
  }
  return k;
}

// MO RAM words of d (MO x = race x + 24, MO y counts up: top line = 256 - MO y - 8 h)
static MarbleAcidMo moWords(const DrawnMo &d, int16_t top) {
  const uint16_t y = (uint16_t)(top + 256 - d.top - 8 * d.h);
  const uint16_t x = (uint16_t)(d.x + 24);
  return {(uint16_t)(((y << 5) & 0x3fe0) | (d.flip ? 0x8000 : 0) | (d.h - 1)),
          (uint16_t)(PAL_ACID << 11), (uint16_t)((x << 5) & 0x3fe0)};
}

// Published acid (build at the arcade cull) against the acid MOs MAME emitted in every fixture
// tick: frame columns (position, height, flip, palette set 6), no masks
static void test_acid_objects(void) {
  uint16_t drawn = 0;
  for (uint8_t sg = 0; sg < MARBLE_ACID_SEGMENTS; sg++) {
    const MarbleAcidSegment &seg = marble_acid_segments[sg];
    loadRam(seg);
    Mem m(ram, seg.race);
    const int16_t descTop = m.desc().top;

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleAcidTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      marble_video::VideoState v = {};
      v.level = seg.race;
      TEST_ASSERT_TRUE(marble_drawlist::build(m, (int16_t)t.camera, 0, v) <= marble_video::OBJS);
      const int16_t top = (int16_t)((int16_t)t.camera - descTop);

      for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) {
        const MarbleAcidObj &s = t.a[i];
        char msg[100];
        snprintf(msg, sizeof(msg), "segment %d tick %d acid %d", sg, k, i);
        DrawnMo got[MOS_MAX];
        const uint8_t n = acidMos(m, v, i, top, got);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(s.n, n, msg);
        for (uint8_t j = 0; j < n; j++) {
          const MarbleAcidMo &e = seg.mos[s.first + j];
          const MarbleAcidMo w = moWords(got[j], top);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w0, w.w0, msg);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w2, w.w2, msg);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code >> 11, PAL_ACID, msg);
        }
        drawn += n != 0;
      }
    }
  }
  printf("acid objects: %u acid ticks drawn\n", drawn);
  TEST_ASSERT_TRUE(drawn > 0);
}

// ---------------------------------------------------------------- race start path

// machine race start (marble.cpp beginRace) on a cleared work RAM
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// live acid <=> exactly one type 0x0e draw list entry
static void checkListed(const Mem &m, uint8_t race, int16_t cam) {
  for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) {
    const uint8_t want = m.rb(acid(i) + SLOT) ? 1 : 0;
    if (listedCount(m, TYPE_ACID, i) == want) { continue; }
    char msg[80];
    snprintf(msg, sizeof(msg), "race %d cam %d: acid %d live %d, draw list differs", race, cam, i,
             want);
    TEST_FAIL_MESSAGE(msg);
  }
}

// marble_acid.py sweep: acid spawns and removals in the camera loop, most live, per race
struct SweepCount { uint8_t spawns, removals, live; };
static const SweepCount SWEEP[RACES] = {{0, 0, 0}, {0, 0, 0}, {21, 21, 7}, {0, 0, 0}, {0, 0, 0},
                                        {8, 10, 4}};

// Race sweep (marble_acid.py sweep): race start, then the camera over the whole race in 4 line
// steps, back, again, player idle; every enemy runs each tick. No abort, acid spawns only at
// their table bands, a draw list entry iff live, objects within OBJS.
static void test_race_sweep(void) {
  for (uint8_t race = 0; race < RACES; race++) {
    beginRace(race);
    Mem m(ram, race);
    const int16_t top = m.desc().top;
    const int16_t range = m.desc().range;
    const int16_t n = range / SWEEP_STEP + 1;
    uint8_t spawns = 0, removals = 0, most = 0;
    uint32_t tick = 0;
    for (uint8_t pass = 0; pass < 3; pass++) {
      for (int16_t j = 0; j < n; j++) {
        int16_t step = pass == 1 ? n - 1 - j : j;  // there, back, there
        if (race == RACE_SILLY) { step = n - 1 - step; }
        const int16_t cam = top + SWEEP_STEP * step;
        uint8_t before[marble_enemies::NACIDS];
        for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) { before[i] = m.rb(acid(i) + SLOT); }
        mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
        marble_video::VideoState v = {};
        TEST_ASSERT_TRUE(marble_drawlist::build(m, cam, 24, v) <= marble_video::OBJS);

        uint8_t live = 0;
        for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) {
          const uint32_t a = acid(i);
          live += m.rb(a + SLOT) != 0;
          if (!before[i] && m.rb(a + SLOT)) {
            spawns++;
            const int16_t band = (int16_t)(cam - top) >> 4;
            TEST_ASSERT_TRUE_MESSAGE(band == m.sw(a + A_BAND_LO) || band == m.sw(a + A_BAND_HI),
                                     "acid spawned outside its bands");
          }
          if (before[i] && !m.rb(a + SLOT)) { removals++; }
        }
        if (live > most) { most = live; }
        checkListed(m, race, cam);
      }
    }
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: spawns, removals, most live", race);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].spawns, spawns, msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].removals, removals, msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].live, most, msg);
  }
}

// camera stepped down the race from its top until an acid lives; its index, -1 if none
static int8_t firstAcid(Mem &m, int16_t &cam, uint32_t &tick) {
  const int16_t top = m.desc().top;
  const int16_t range = m.desc().range;
  for (cam = top; cam <= top + range; cam += SWEEP_STEP) {
    mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
    for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) {
      if (m.rb(acid(i) + SLOT)) { return (int8_t)i; }
    }
  }
  return -1;
}

// the player put on acid a (position, ground, zone), standing still
static void placeOn(Mem &m, uint32_t a) {
  m.wl(PLAYER + 0x00, 0);
  m.wl(PLAYER + 0x04, 0);
  m.wl(PLAYER + PX, m.rl(a + PX));
  m.wl(PLAYER + PY, m.rl(a + PY));
  m.wl(PLAYER + PZ, m.rl(a + PZ));
  m.wb(PLAYER + ZONE, m.rb(a + ZONE));
}

// In every acid race the marble put on an acid dissolves: player DISSOLVING, LOST, then
// rolling again; the draw list stays consistent. A race switch while dissolving starts as
// from a cleared work RAM.
static void test_dissolve_and_switch(void) {
  static const uint8_t ACID_RACES[] = {2, 5};
  for (uint8_t race : ACID_RACES) {
    beginRace(race);
    Mem m(ram, race);
    int16_t cam = 0;
    uint32_t tick = 0;
    const int8_t live = firstAcid(m, cam, tick);
    TEST_ASSERT_TRUE_MESSAGE(live >= 0, "no acid spawned");

    placeOn(m, acid((uint8_t)live));
    bool dissolved = false, lost = false;
    uint16_t k = 0;
    for (; k < DISSOLVE_TICKS; k++) {
      mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
      const uint8_t st = marble_physics::state(m);
      dissolved |= st == marble_physics::DISSOLVING;
      lost |= dissolved && st == marble_physics::LOST;
      checkListed(m, race, cam);
      if (lost && st == marble_physics::ROLL) { break; }
    }
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: dissolved, lost, rolling", race);
    TEST_ASSERT_TRUE_MESSAGE(dissolved && lost && k < DISSOLVE_TICKS, msg);

    // dissolving again, switch race mid dissolve
    placeOn(m, acid((uint8_t)live));
    for (k = 0; k < DISSOLVE_TICKS && marble_physics::state(m) != marble_physics::DISSOLVING;
         k++) {
      mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
    }
    TEST_ASSERT_EQUAL_UINT8(marble_physics::DISSOLVING, marble_physics::state(m));
    const uint8_t next = (race + 1) % RACES;
    beginRace(next);
    static uint8_t clean[marble_physics::RAM_SIZE];
    memcpy(clean, ram, sizeof(ram));
    beginRace(next);
    TEST_ASSERT_EQUAL_MEMORY(clean, ram, sizeof(ram));
    Mem n(ram, next);
    TEST_ASSERT_EQUAL_UINT8(marble_physics::ROLL, marble_physics::state(n));
    for (uint8_t i = 0; i < marble_enemies::NACIDS; i++) {
      TEST_ASSERT_EQUAL_UINT8(i, n.rb(acid(i) + IDX));
      TEST_ASSERT_EQUAL_UINT8(n.rb(acid(i) + SLOT) ? 1 : 0, listedCount(n, TYPE_ACID, i));
    }
  }
}
#endif

int main(int argc, char **argv) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  Arena::reserve(&marble_arena_plan);  // like switchTo()
  marble_physics::loadRom();
  RUN_TEST(test_replay_acid);
  RUN_TEST(test_acid_objects);
  RUN_TEST(test_race_sweep);
  RUN_TEST(test_dissolve_and_switch);
#endif
  return UNITY_END();
}
